export const LANGUAGES = LANGUAGE_INFO.map((item) => item.name);

/** Picker-ready options: language name, flag and native spelling as a hint. */
export const LANGUAGE_OPTIONS = LANGUAGE_INFO.map((item) => ({
  value: item.name,
  label: item.name,
  code: item.flag,
  hint: item.native !== item.name ? item.native : undefined,
}));

const LANGUAGE_BY_NAME = new Map(LANGUAGE_INFO.map((item) => [item.name.toLowerCase(), item]));

export function languageInfo(name: string): LanguageInfo | undefined {
  return LANGUAGE_BY_NAME.get(name.toLowerCase());
}

const COUNTRY_CODES =
  "af ax al dz as ad ao ai ag ar am aw au at az bs bh bd bb by be bz bj bm bt bo ba bw br bn bg bf bi cv kh cm ca ky cf td cl cn co km cg cd ck cr ci hr cu cw cy cz dk dj dm do ec eg sv gq er ee sz et fo fj fi fr gf pf ga gm ge de gh gi gr gl gd gp gu gt gg gn gw gy ht va hn hk hu is in id ir iq ie im il it jm jp je jo kz ke ki kp kr xk kw kg la lv lb ls lr ly li lt lu mo mg mw my mv ml mt mh mq mr mu yt mx fm md mc mn me ms ma mz mm na nr np nl nc nz ni ne ng mk no om pk pw ps pa pg py pe ph pl pt pr qa re ro ru rw ws sm st sa sn rs sc sl sg sx sk si sb so za ss es lk sd sr se ch sy tw tj tz th tl tg to tt tn tr tm tc tv ug ua ae gb us uy uz vu ve vn vg vi ye zm zw".split(
    " ",
  );

export interface CountryInfo {
  code: string;
  name: string;
}

const regionNames = new Intl.DisplayNames(["en"], { type: "region" });

export const COUNTRIES: CountryInfo[] = COUNTRY_CODES.map((code) => ({
  code,
  name: regionNames.of(code.toUpperCase()) ?? code.toUpperCase(),
})).sort((a, b) => a.name.localeCompare(b.name));

const COUNTRY_BY_NAME = new Map(COUNTRIES.map((item) => [item.name.toLowerCase(), item.code]));

/** Best-effort country code for profiles saved before country codes existed. */
export function countryCodeFor(name: string, code?: string): string {
  if (code) return code;
  return COUNTRY_BY_NAME.get(name.trim().toLowerCase()) ?? "";
}

export function flagUrl(code: string): string {
  return `https://flagcdn.com/${code.toLowerCase()}.svg`;
}
